        selectedObstacleIndex: 2,
        trafficPlacement: { index: 2, mode: "waypoint" },
        activeDrag: {
          hit: { index: 2, handle: { kind: "body" } },
          pointerId: 1,
          phase: "candidate",
          downClient: { x: 0, y: 0 },
        },
      },
    );
    expect(state.selectedObstacleIndex).toBe(1);
